#include "json.hpp"
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <stdexcept>

namespace blitz::lsp {
	static const json null_value;

	json const& json::operator[](std::string const& key) const
	{
		if (_type == type::object) {
			if (auto found = _object.find(key); found != _object.end()) {
				return found->second;
			}
		}
		return null_value;
	}

	json const& json::operator[](size_t index) const
	{
		return ((_type == type::array) && (index < _array.size())) ? _array[index] : null_value;
	}

	json& json::set(std::string const& key, json value)
	{
		_type = type::object;
		_object[key] = std::move(value);
		return *this;
	}

	json& json::set_default(std::string const& key)
	{
		_type = type::object;
		return _object[key];
	}

	json& json::push(json value)
	{
		_type = type::array;
		_array.push_back(std::move(value));
		return *this;
	}

	static void write_string(std::string& out, std::string const& text)
	{
		out += '"';
		for (unsigned char c : text) {
			switch (c) {
			case '"': out += "\\\""; break;
			case '\\': out += "\\\\"; break;
			case '\n': out += "\\n"; break;
			case '\r': out += "\\r"; break;
			case '\t': out += "\\t"; break;
			default:
				if (c < 0x20) {
					char buffer[8];
					snprintf(buffer, sizeof(buffer), "\\u%04x", c);
					out += buffer;
				} else {
					out += char(c);
				}
			}
		}
		out += '"';
	}

	void json::write(std::string& out) const
	{
		switch (_type) {
		case type::null: out += "null"; break;
		case type::boolean: out += _bool ? "true" : "false"; break;
		case type::number: {
			char buffer[32];
			if (std::floor(_number) == _number && std::fabs(_number) < 9e15) {
				snprintf(buffer, sizeof(buffer), "%lld", static_cast<long long>(_number));
			} else {
				snprintf(buffer, sizeof(buffer), "%.17g", _number);
			}
			out += buffer;
			break;
		}
		case type::string: write_string(out, _string); break;
		case type::array: {
			out += '[';
			bool first = true;
			for (auto const& item : _array) {
				if (!first) out += ',';
				first = false;
				item.write(out);
			}
			out += ']';
			break;
		}
		case type::object: {
			out += '{';
			bool first = true;
			for (auto const& [key, value] : _object) {
				if (!first) out += ',';
				first = false;
				write_string(out, key);
				out += ':';
				value.write(out);
			}
			out += '}';
			break;
		}
		}
	}

	std::string json::dump() const
	{
		std::string out;
		write(out);
		return out;
	}

	namespace {
		struct reader {
			std::string const& s;
			size_t             at = 0;
			int                depth = 0;

			[[noreturn]] void fail(const char* why) const { throw std::runtime_error(std::string("invalid JSON: ") + why + " at " + std::to_string(at)); }
			void skip() { while (at < s.size() && (s[at] == ' ' || s[at] == '\t' || s[at] == '\n' || s[at] == '\r')) at++; }
			bool eat(char c) { skip(); if (at < s.size() && s[at] == c) { at++; return true; } return false; }

			static void utf8(std::string& out, uint32_t cp)
			{
				if (cp < 0x80) out += char(cp);
				else if (cp < 0x800) { out += char(0xC0 | (cp >> 6)); out += char(0x80 | (cp & 0x3F)); }
				else if (cp < 0x10000) { out += char(0xE0 | (cp >> 12)); out += char(0x80 | ((cp >> 6) & 0x3F)); out += char(0x80 | (cp & 0x3F)); }
				else { out += char(0xF0 | (cp >> 18)); out += char(0x80 | ((cp >> 12) & 0x3F)); out += char(0x80 | ((cp >> 6) & 0x3F)); out += char(0x80 | (cp & 0x3F)); }
			}

			uint32_t hex4()
			{
				if (at + 4 > s.size()) fail("short escape");
				uint32_t v = 0;
				for (int i = 0; i < 4; i++) {
					char c = s[at++];
					v <<= 4;
					if (c >= '0' && c <= '9') v |= c - '0';
					else if (c >= 'a' && c <= 'f') v |= c - 'a' + 10;
					else if (c >= 'A' && c <= 'F') v |= c - 'A' + 10;
					else fail("bad escape");
				}
				return v;
			}

			std::string string()
			{
				std::string out;
				while (at < s.size()) {
					char c = s[at++];
					if (c == '"') return out;
					if (c != '\\') { out += c; continue; }
					if (at >= s.size()) break;
					char e = s[at++];
					switch (e) {
					case 'n': out += '\n'; break;
					case 'r': out += '\r'; break;
					case 't': out += '\t'; break;
					case 'b': out += '\b'; break;
					case 'f': out += '\f'; break;
					case 'u': {
						uint32_t cp = hex4();
						if (cp >= 0xD800 && cp < 0xDC00 && at + 1 < s.size() && s[at] == '\\' && s[at + 1] == 'u') {
							at += 2;
							uint32_t low = hex4();
							cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
						}
						utf8(out, cp);
						break;
					}
					default: out += e;
					}
				}
				fail("unterminated string");
			}

			json value()
			{
				skip();
				if (at >= s.size()) fail("unexpected end");
				if (++depth > 200) fail("too deep");
				struct leave { int& d; ~leave() { d--; } } guard{ depth };
				char c = s[at];
				if (c == '{') {
					at++;
					json o = json::object();
					if (eat('}')) return o;
					do {
						skip();
						if (at >= s.size() || s[at] != '"') fail("expected a key");
						at++;
						std::string key = string();
						if (!eat(':')) fail("expected ':'");
						o.set(key, value());
					} while (eat(','));
					if (!eat('}')) fail("expected '}'");
					return o;
				}
				if (c == '[') {
					at++;
					json a = json::array();
					if (eat(']')) return a;
					do { a.push(value()); } while (eat(','));
					if (!eat(']')) fail("expected ']'");
					return a;
				}
				if (c == '"') { at++; return json(string()); }
				if (s.compare(at, 4, "true") == 0) { at += 4; return json(true); }
				if (s.compare(at, 5, "false") == 0) { at += 5; return json(false); }
				if (s.compare(at, 4, "null") == 0) { at += 4; return json(); }
				char* end = nullptr;
				double number = std::strtod(s.c_str() + at, &end);
				if (end == s.c_str() + at) fail("unexpected character");
				at = size_t(end - s.c_str());
				return json(number);
			}
		};
	} // namespace

	json json::parse(std::string const& text)
	{
		reader r{ text };
		json   v = r.value();
		r.skip();
		if (r.at != text.size()) r.fail("trailing characters");
		return v;
	}
} // namespace blitz::lsp
